    """Return n with bits i through j replaced by m."""
    pass

problems.reference_solution:
def insert_bits(n, m, i, j):
    """Return n with bits i through j replaced by m."""
    mask = ((1 << (j - i + 1)) - 1) << i
    return (n & ~mask) | (m << i)

