problems.reference_solution:
def to_bits(text):
    """Return the bits of text encoded as UTF-8, most significant bit of each byte first."""
    return [(byte >> shift) & 1 for byte in text.encode('utf-8') for shift in range(7, -1, -1)]


def from_bits(bits):
    """Return the text whose UTF-8 bits, as to_bits gives them, are bits."""
    data = bytearray()
    for start in range(0, len(bits), 8):
        byte = 0
        for bit in bits[start : start + 8]:
            byte = byte << 1 | bit
        data.append(byte)
    return data.decode('utf-8')

