def decode(word):
    """Return the 4 data bits of a Hamming(7,4) word, correcting one flipped bit."""
    pass

problems.reference_solution:
def decode(word):
    """Return the 4 data bits of a Hamming(7,4) word, correcting one flipped bit."""
    bits = [0] + list(word)
    wrong = 0
    for parity in (1, 2, 4):
        ones = sum(bits[position] for position in range(1, 8) if position & parity)
        if ones % 2:
            wrong += parity
    if wrong:
        bits[wrong] ^= 1
    return [bits[3], bits[5], bits[6], bits[7]]

problems.tests:
from solution import *


def _encode(data):
    bits = [0] * 8
    for position, bit in zip((3, 5, 6, 7), data):
        bits[position] = bit
    for parity in (1, 2, 4):
        bits[parity] = sum(bits[p] for p in range(1, 8) if p & parity and p != parity) % 2
    return bits[1:]


def _all_data():
    return [[(value >> shift) & 1 for shift in (3, 2, 1, 0)] for value in range(16)]


def test_example_1():
    """A word with no error."""
    assert decode([0, 1, 1, 0, 0, 1, 1]) == [1, 0, 1, 1]


def test_example_2():
    """A word with position 5 flipped."""
    assert decode([0, 1, 1, 0, 1, 1, 1]) == [1, 0, 1, 1]


def test_all_zeros_and_ones():
    """The words for 0000 and 1111."""
    assert decode([0] * 7) == [0, 0, 0, 0]
    assert decode([1] * 7) == [1, 1, 1, 1]


def test_flipped_parity_bit():
    """A flipped parity bit leaves the data as it is."""
    assert decode([1, 1, 1, 0, 0, 1, 1]) == [1, 0, 1, 1]


def test_every_word_without_error():
    """All 16 data values, sent without error."""
    for data in _all_data():
        assert decode(_encode(data)) == data


def test_every_single_flip():
    """All 16 data values with each of the 7 positions flipped."""
    for data in _all_data():
        for position in range(7):
            word = _encode(data)
            word[position] ^= 1
            assert decode(word) == data, (data, position + 1)


def test_input_unchanged():
    """The given word is not changed."""
    word = [0, 1, 1, 0, 1, 1, 1]
    decode(word)
    assert word == [0, 1, 1, 0, 1, 1, 1]

