problems.reference_solution:
def primes_up_to(n):
    """Return the primes from 2 to n, inclusive, in ascending order."""
    if n < 2:
        return []
    prime = bytearray([1]) * (n + 1)
    prime[0] = prime[1] = 0
    for factor in range(2, int(n**0.5) + 1):
        if prime[factor]:
            prime[factor * factor :: factor] = bytes(len(range(factor * factor, n + 1, factor)))
    return [value for value in range(n + 1) if prime[value]]
